// TestPlaybackDecisionReason covers the resolver's precedence (D8): hls is
// always `packaged` (even with a live cooldown — an older build still
// serves), a live pack-failed ledger row beats the failed state (`cooldown`
// — retry later) and decays into `failed` once it expires, the descriptor's
// honesty reason rides through for a none-state non-native floor, and a
// plain native floor is `unpackaged`.
func TestPlaybackDecisionReason(t *testing.T) {
	now := time.Unix(1_800_000_000, 0)
	live := now.Add(time.Hour)
	expired := now.Add(-time.Hour)
	for _, tc := range []struct {
		name        string
		mode        string
		state       string
		stateReason string
		coolUntil   time.Time
		want        string
	}{
		{"hls_is_packaged", stream.ModeHls, stream.StateComplete, "", time.Time{}, reasonPackaged},
		{"hls_with_live_cooldown_still_packaged", stream.ModeHls, stream.StateNone, "", live, reasonPackaged},
		{"live_cooldown_beats_failed", stream.ModeDirect, stream.StateFailed, stream.ReasonNonNativeContainer, live, reasonCooldown},
		{"expired_cooldown_reports_failed", stream.ModeDirect, stream.StateFailed, "", expired, reasonFailed},
		{"failed_without_cooldown", stream.ModeDirect, stream.StateFailed, "", time.Time{}, reasonFailed},
		{"non_native_container_rides_through", stream.ModeDirect, stream.StateNone, stream.ReasonNonNativeContainer, time.Time{}, stream.ReasonNonNativeContainer},
		{"codec_not_opted_in_rides_through", stream.ModeDirect, stream.StateNone, stream.ReasonCodecNotOptedIn, time.Time{}, stream.ReasonCodecNotOptedIn},
		{"codec_unsupported_rides_through", stream.ModeDirect, stream.StateNone, stream.ReasonCodecUnsupported, time.Time{}, stream.ReasonCodecUnsupported},
		{"native_floor_unpackaged", stream.ModeDirect, stream.StateNone, "", time.Time{}, reasonUnpackaged},
	} {
		t.Run(tc.name, func(t *testing.T) {
			got := playbackDecisionReason(tc.mode, tc.state, tc.stateReason, tc.coolUntil, now)
			if got != tc.want {
				t.Errorf("playbackDecisionReason(%q, %q, %q, cool=%v) = %q, want %q",
					tc.mode, tc.state, tc.stateReason, tc.coolUntil, got, tc.want)
			}
		})
	}
}

// TestPlaybackDecisionLog drives the real Deps.Playback closure body (the
// composition root's descriptor GET path) over a real store and stream
// Service with logging captured (the spec's acceptance record): each fetch
// logs exactly ONE decision line carrying item/mode/state/reason, the
// reasons cover the full vocabulary (packaged / non_native_container /
// codec_not_opted_in / codec_unsupported / cooldown / unpackaged), and no
// captured line ever carries the media token value or the play URL (INV4).
// The GET stays read-only: the seeded packaging state is unchanged after
// every fetch.
func TestPlaybackDecisionLog(t *testing.T) {
	ctx := context.Background()
	st := openJanitorStore(t)
	mediaSvc := &stream.Service{Root: t.TempDir(), Secret: []byte("decision-log-test-secret")}

	seedItem := func(t *testing.T, id string, doc map[string]any) {
		t.Helper()
		raw, err := json.Marshal(doc)
		if err != nil {
			t.Fatalf("marshal doc for %s: %v", id, err)
		}
		if err := st.PutItem(ctx, store.Item{
			ID: id, ModuleID: "serial", LibraryID: 1, FileID: id, RelativePath: id + ".mkv",
			MediaType: "movie", Document: raw, SchemaVersion: 1,
		}); err != nil {
			t.Fatalf("PutItem %s: %v", id, err)
		}
	}
	// ffDoc builds the ffprobe blob the honesty projection reads: one video
	// stream with the given codec/pixel format, one aac audio track, and the
	// container's format_name.
	ffDoc := func(format, codec, pixFmt string) map[string]any {
		video := map[string]any{"codec_type": "video", "codec_name": codec}
		if pixFmt != "" {
			video["pix_fmt"] = pixFmt
		}
		return map[string]any{
			"format":  map[string]any{"format_name": format},
			"streams": []any{video, map[string]any{"codec_type": "audio", "codec_name": "aac"}},
		}
	}

	seedItem(t, "pkg-item", map[string]any{"streams": map[string]any{
		"state": stream.StateComplete, "playlist": "/media/pkg-item/n1/index.m3u8"}})
	seedItem(t, "mkv-item", map[string]any{"ffprobe": ffDoc("matroska,webm", "h264", "")})
	seedItem(t, "hevc-item", map[string]any{"ffprobe": ffDoc("matroska,webm", "hevc", "")})
	seedItem(t, "codec-item", map[string]any{"ffprobe": ffDoc("matroska,webm", "h264", "yuv420p10le")})
	seedItem(t, "mp4-item", map[string]any{"ffprobe": ffDoc("mp4", "h264", "")})
	seedItem(t, "cool-item", map[string]any{
		"streams": map[string]any{"state": stream.StateFailed},
		"ffprobe": ffDoc("matroska,webm", "h264", ""),
	})
	coolUntil := time.Now().Add(time.Hour)
	if err := st.RecordFailure(ctx, "cool-item", streamsFailureLane, "failed", "ffmpeg exit 1", 1, coolUntil); err != nil {
		t.Fatalf("RecordFailure: %v", err)
	}

	// Capture the default logger for the whole pass (the watch_defaults_test
	// precedent; never parallel).
	var buf bytes.Buffer
	prev := slog.Default()
	slog.SetDefault(slog.New(slog.NewTextHandler(&buf, nil)))
	t.Cleanup(func() { slog.SetDefault(prev) })

	for _, tc := range []struct {
		id        string
		mode      string
		state     string // the descriptor's state (honesty projections included)
		persisted string // the stored namespace's state ("" = same as state)
		have      string // state_reason the descriptor itself must answer ("" = absent)
		want      string // the decision line's reason
	}{
		{"pkg-item", stream.ModeHls, stream.StateComplete, "", "", reasonPackaged},
		// The honesty projection (tv-playback-unblock D1): a none-state
		// non-native floor answers preparing/unsupported on the descriptor
		// while the persisted namespace stays at none.
		{"mkv-item", stream.ModeDirect, stream.StatePreparing, stream.StateNone, stream.ReasonNonNativeContainer, stream.ReasonNonNativeContainer},
		{"hevc-item", stream.ModeDirect, stream.StateUnsupported, stream.StateNone, stream.ReasonCodecNotOptedIn, stream.ReasonCodecNotOptedIn},
		{"codec-item", stream.ModeDirect, stream.StateUnsupported, stream.StateNone, stream.ReasonCodecUnsupported, stream.ReasonCodecUnsupported},
		{"mp4-item", stream.ModeDirect, stream.StateNone, "", "", reasonUnpackaged},
		{"cool-item", stream.ModeDirect, stream.StateFailed, "", stream.ReasonNonNativeContainer, reasonCooldown},
	} {
		t.Run(tc.id, func(t *testing.T) {
			buf.Reset()
			pb, err := playbackDescriptor(ctx, st, mediaSvc, tc.id)
			if err != nil {
				t.Fatalf("playbackDescriptor(%s): %v", tc.id, err)
			}
			if pb.Mode != tc.mode || pb.State != tc.state {
				t.Fatalf("descriptor = %s/%s, want %s/%s", pb.Mode, pb.State, tc.mode, tc.state)
			}
			if pb.StateReason != tc.have {
				t.Fatalf("descriptor state_reason = %q, want %q", pb.StateReason, tc.have)
			}

			// Exactly ONE decision line per GET, carrying item/mode/state/reason.
			var lines []string
			for _, ln := range strings.Split(strings.TrimSpace(buf.String()), "\n") {
				if strings.Contains(ln, `msg="playback: descriptor"`) && strings.Contains(ln, "item="+tc.id) {
					lines = append(lines, ln)
				}
			}
			if len(lines) != 1 {
				t.Fatalf("captured %d decision lines for %s, want 1; output:\n%s", len(lines), tc.id, buf.String())
			}
			for _, field := range []string{
				"mode=" + tc.mode, "state=" + tc.state, "reason=" + tc.want,
			} {
				if !strings.Contains(lines[0], field) {
					t.Fatalf("decision line %q lacks %q", lines[0], field)
				}
			}

			// INV4: neither the play URL nor either minted token value may
			// appear anywhere in the captured log.
			for _, tok := range []string{queryToken(pb.PlayURL), pb.Token} {
				if tok != "" && strings.Contains(buf.String(), tok) {
					t.Fatalf("captured log carries a media token value (INV4): output:\n%s", buf.String())
				}
			}
			if strings.Contains(buf.String(), pb.PlayURL) {
				t.Fatalf("captured log carries the play URL (INV4): output:\n%s", buf.String())
			}

			// Read-only: the GET never mutates packaging state.
			row, err := st.GetItem(ctx, tc.id)
			if err != nil {
				t.Fatalf("re-GetItem %s: %v", tc.id, err)
			}
			var after map[string]any
			if err := json.Unmarshal(row.Document, &after); err != nil {
				t.Fatalf("re-decode %s: %v", tc.id, err)
			}
			streams, _ := after["streams"].(map[string]any)
			state, _ := streams["state"].(string)
			if state == "" { // absent namespace reads as none (streamState's fallback)
				state = stream.StateNone
			}
			wantPersisted := tc.persisted
			if wantPersisted == "" {
				wantPersisted = tc.state
			}
			if state != wantPersisted {
				t.Fatalf("GET mutated packaging state for %s: %q, want %q", tc.id, state, wantPersisted)
			}
		})
	}
}

// queryToken extracts the token query value from a /media play URL.
func queryToken(playURL string) string {
	u, err := url.Parse(playURL)
	if err != nil {
		return ""
	}
	return u.Query().Get("token")
}
